package com.savora.model; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="orders") public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) public User user; @ManyToOne(optional=false) public Restaurant restaurant; @ManyToOne public Address address; @Enumerated(EnumType.STRING) public OrderStatus status=OrderStatus.PLACED; public BigDecimal subtotal,tax,deliveryFee,discount=BigDecimal.ZERO,total; public String coupon; public Instant createdAt=Instant.now(); @OneToMany(mappedBy="order",cascade=CascadeType.ALL) public List<OrderItem> items=new ArrayList<>(); }
